create extension if not exists pgcrypto;

create table if not exists public.sessions (
    id varchar(255) primary key,
    user_id bigint null,
    ip_address varchar(45) null,
    user_agent text null,
    payload text not null,
    last_activity integer not null
);
create index if not exists sessions_user_id_index on public.sessions (user_id);
create index if not exists sessions_last_activity_index on public.sessions (last_activity);

create table if not exists public.cache (
    key varchar(255) primary key,
    value text not null,
    expiration integer not null
);
create table if not exists public.cache_locks (
    key varchar(255) primary key,
    owner varchar(255) not null,
    expiration integer not null
);

create table if not exists public.users (id bigint generated by default as identity primary key, username varchar(50) not null unique, password varchar(255) not null, full_name varchar(100) not null, email varchar(100), phone varchar(20), role varchar(20) not null default 'employee' check (role in ('admin','employee')), avatar varchar(255) default 'default_avatar.png', status varchar(20) not null default 'active' check (status in ('active','inactive')), archived smallint not null default 0 check (archived in (0, 1)), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.barangays (id bigint generated by default as identity primary key, barangay_name varchar(100) not null unique, latitude numeric(10,8) not null default 0, longitude numeric(11,8) not null default 0, description text, created_at timestamptz not null default now());
